# -*- coding: utf-8 -*-
"""Generate Vietnamese localization Liquibase seed migration for manager-api.

Scans db/changelog/*.sql DML for Chinese (Han) string literals, applies a
Chinese→Vietnamese glossary (exact + longest-first phrase replace), and writes:
  main/manager-api/src/main/resources/db/changelog/202608131200.sql
Also appends the changeset to db.changelog-master.yaml.
Untranslated remaining unique strings are printed to stderr.

GLOSSARY maps Chinese → Vietnamese for seed UI strings.
"""
from __future__ import annotations

import json
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
CHANGELOG_DIR = ROOT / "main/manager-api/src/main/resources/db/changelog"
OUT_SQL = CHANGELOG_DIR / "202608131200.sql"
MASTER_YAML = CHANGELOG_DIR / "db.changelog-master.yaml"
HAN_RE = re.compile(r"[\u4e00-\u9fff]")
STRING_RE = re.compile(r"'(?:''|\\'|[^'])*'")
DML_RE = re.compile(
    r"(?:INSERT\s+INTO|UPDATE)\s+[`]?(?P<table>\w+)[`]?[^;]*;",
    re.IGNORECASE | re.DOTALL,
)

TABLE_COLUMNS: dict[str, list[str]] = {
    "ai_model_provider": ["name", "fields"],
    "ai_model_config": ["model_name", "remark", "config_json"],
    "ai_tts_voice": ["name", "languages", "remark"],
    # param_value often holds wake words / machine config — only translate remark.
    "sys_params": ["remark"],
    "sys_dict_type": ["dict_name", "remark"],
    "sys_dict_data": ["dict_label", "remark"],
    "ai_agent_template": ["agent_code", "agent_name", "system_prompt", "language"],
}

# Exact param_code updates for user-visible Chinese default replies (not wake words).
