def sql_escape(s: str) -> str:
    return s.replace("\\", "\\\\").replace("'", "''")


# Chunk nested REPLACE to stay under typical MySQL expression-depth limits.
REPLACE_CHUNK_SIZE = 40

# Single-char / particle keys corrupt already-translated text if used in REPLACE.
MIN_GLOSSARY_KEY_LEN = 2
GLOSSARY_KEY_BLACKLIST = {
    "的",
    "管理",
    "参数",
    "是",
    "在",
    "中",
    "和",
    "不",
    "仅",
    "种",
    "等",
    "可",
    "一",
    "二",
    "后",
    "该",
    "与",
    "元",
    "英",
    "日",
    "了",
    "大",
    "多",
    "数",
    "时",
    "下",
    "前",
    "为",
    "就",
    "会",
    "有",
    "个",
    "才",
    "要",
    "看",
    "之",
    "其",
    "而",
    "这",
    "了大",
    "的值",
    "中添加",
    "字段中",
    "种值",
    "下的",
    "下注册",
    "下注册新",
    "项目的",
    "请求的",
    "前请在",
    "和设置",
    "和并发版",
    "须和",
}


def sanitize_glossary(glossary: dict[str, str]) -> dict[str, str]:
    """Drop destructive short/particle keys and empty translations."""
    out: dict[str, str] = {}
    for k, v in glossary.items():
        if not k or k in GLOSSARY_KEY_BLACKLIST:
            continue
        if len(k) < MIN_GLOSSARY_KEY_LEN:
            continue
        if v is None:
            continue
        # Allow intentional identity for proper nouns (Japanese voice names).
        if not str(v).strip() and k != v:
            continue
        out[k] = v
    return out


def extract_chinese_from_statement(stmt: str) -> list[str]:
    found: list[str] = []
    for sm in STRING_RE.finditer(stmt):
        lit = sm.group(0)[1:-1].replace("''", "'").replace("\\'", "'")
        if HAN_RE.search(lit):
            found.append(lit)
    return found


def extract_chinese_literals(text: str) -> list[str]:
    lines = []
    for line in text.splitlines():
        if line.lstrip().startswith("--"):
            continue
        lines.append(line)
    content = "\n".join(lines)
    found: list[str] = []
    for m in DML_RE.finditer(content):
        found.extend(extract_chinese_from_statement(m.group(0)))
    return found


def scan_chinese_by_table() -> dict[str, set[str]]:
    """Chinese literals found in INSERT/UPDATE for each target table."""
    by_table: dict[str, set[str]] = {t: set() for t in TABLE_COLUMNS}
    for path in sorted(CHANGELOG_DIR.glob("*.sql")):
        if path.name == OUT_SQL.name:
            continue
        lines = []
        for line in path.read_text(encoding="utf-8").splitlines():
            if line.lstrip().startswith("--"):
                continue
            lines.append(line)
        content = "\n".join(lines)
        for m in DML_RE.finditer(content):
            table = m.group("table")
            if table not in by_table:
                continue
            by_table[table].update(extract_chinese_from_statement(m.group(0)))
    return by_table


def scan_all_chinese() -> set[str]:
    unique: set[str] = set()
    for path in sorted(CHANGELOG_DIR.glob("*.sql")):
        if path.name == OUT_SQL.name:
            continue
        unique.update(extract_chinese_literals(path.read_text(encoding="utf-8")))
    return unique


def apply_glossary(text: str, glossary: dict[str, str]) -> str:
    if text in glossary:
        return glossary[text]
    keys = sorted(glossary.keys(), key=len, reverse=True)
    out = text
    for k in keys:
        if k and k in out:
            out = out.replace(k, glossary[k])
    return out


def filter_glossary_used(glossary: dict[str, str], corpus: set[str]) -> dict[str, str]:
    used: dict[str, str] = {}
    for k, v in glossary.items():
        for s in corpus:
            if k in s:
                used[k] = v
                break
    return used


def nested_replace_expr(column_expr: str, pairs: list[tuple[str, str]]) -> str:
    expr = column_expr
    for zh, vi in pairs:
        expr = f"REPLACE({expr}, '{sql_escape(zh)}', '{sql_escape(vi)}')"
    return expr


def chunked(seq: list[tuple[str, str]], size: int) -> list[list[tuple[str, str]]]:
    return [seq[i : i + size] for i in range(0, len(seq), size)]


def looks_like_display_name(s: str) -> bool:
    """Heuristic: short UI names, not help-doc / remark snippets."""
    if len(s) > 40 or "\n" in s:
        return False
    if any(c in s for c in "，。；；"):
        return False
    markers = (
        "配置说明",
        "申请步骤",
        "http://",
        "https://",
        "使用步骤",
        "参数说明",
        "注意：",
        "【",
        "```",
    )
    if any(m in s for m in markers):
        return False
    # Remark-style sentences often start with these verbs.
    if s.startswith(("支持", "使用", "需要", "通过", "具有", "适合", "如果", "可以", "默认")):
        return False
    return True



def pairs_for_column(
    table_used: dict[str, str], table_corpus: set[str], column: str
) -> list[tuple[str, str]]:
    """Build REPLACE pairs for one column.

    Short display columns only get exact full-literal replacements that look like
    names (not help-doc snippets), so model_name/name stay clean.
    """
    short_display = {
        "name",
        "model_name",
        "agent_code",
        "agent_name",
        "language",
        "languages",
        "dict_name",
        "dict_label",
    }
    pairs: dict[str, str] = {}

    if column in short_display:
        for lit in table_corpus:
            if lit in table_used and looks_like_display_name(lit):
                pairs[lit] = table_used[lit]
        return sorted(pairs.items(), key=lambda kv: len(kv[0]), reverse=True)

    if column == "fields":
        relevant = {lit for lit in table_corpus if len(lit) <= 4000}
    else:
        relevant = set(table_corpus)

    for lit in relevant:
        if lit in table_used:
            pairs[lit] = table_used[lit]

    for k, v in table_used.items():
        if k in pairs:
            continue
        if any(k in lit for lit in relevant):
            pairs[k] = v

    return sorted(pairs.items(), key=lambda kv: len(kv[0]), reverse=True)





def generate_sql(used: dict[str, str], by_table: dict[str, set[str]]) -> str:
    lines = [
        "-- Vietnamese localization of seed display strings for manager-web",
        "-- Generated by scripts/gen_vi_seed_migration.py",
        "-- Uses nested REPLACE; keys sorted longest-first to avoid partial-replace bugs.",
        "-- Per-table/column key sets; REPLACE chunked to limit expression depth.",
        "-- Short particle keys are excluded to avoid corrupting translated text.",
        "",
    ]
    for table, columns in TABLE_COLUMNS.items():
        table_corpus = by_table.get(table, set())
        table_used = filter_glossary_used(used, table_corpus) if table_corpus else {}
        if not table_used:
            lines.append(f"-- {table}: no Chinese seed strings matched")
            lines.append("")
            continue
        lines.append(f"-- {table}")
        for col in columns:
            pairs = pairs_for_column(table_used, table_corpus, col)
            if not pairs:
                lines.append(f"--   {col}: skipped (no keys)")
                continue
            chunks = chunked(pairs, REPLACE_CHUNK_SIZE)
            lines.append(f"--   {col}: {len(pairs)} keys, {len(chunks)} chunk(s)")
            for chunk in chunks:
                expr = nested_replace_expr(f"`{col}`", chunk)
                lines.append(f"UPDATE `{table}` SET `{col}` = {expr};")
        lines.append("")

    if PARAM_VALUE_TRANSLATIONS:
        lines.append("-- sys_params.param_value: user-visible Chinese defaults only")
        for code, vi in PARAM_VALUE_TRANSLATIONS.items():
            lines.append(
                "UPDATE `sys_params` SET `param_value` = "
                f"'{sql_escape(vi)}' WHERE `param_code` = '{sql_escape(code)}';"
            )
        lines.append("")
    return "\n".join(lines) + "\n"


CHANGESET_SNIPPET = """  - changeSet:
      id: 202608131200
      author: robot-ai-vi
      changes:
        - sqlFile:
            encoding: utf8
            path: classpath:db/changelog/202608131200.sql
"""


def ensure_yaml_changeset() -> bool:
    text = MASTER_YAML.read_text(encoding="utf-8")
    if "202608131200" in text:
        return False
    if not text.endswith("\n"):
        text += "\n"
    MASTER_YAML.write_text(text + CHANGESET_SNIPPET, encoding="utf-8")
    return True


def main() -> int:
    if not CHANGELOG_DIR.is_dir():
        print(f"Changelog dir not found: {CHANGELOG_DIR}", file=sys.stderr)
        return 1

    corpus = scan_all_chinese()
    by_table = scan_chinese_by_table()
    glossary = sanitize_glossary(GLOSSARY)
    used = filter_glossary_used(glossary, corpus)

    # Report remaining against target-table UI strings primarily,
    # but also include any other DML Chinese for visibility.
    remaining: list[str] = []
    for s in sorted(corpus, key=lambda x: (len(x), x)):
        translated = apply_glossary(s, used)
        if HAN_RE.search(translated):
            remaining.append(s)

    OUT_SQL.write_text(generate_sql(used, by_table), encoding="utf-8")
    yaml_updated = ensure_yaml_changeset()

    print(f"Wrote: {OUT_SQL}")
    print(f"Glossary entries used: {len(used)}")
    print(f"Unique Chinese strings scanned: {len(corpus)}")
    print(f"Remaining untranslated: {len(remaining)}")
    print(f"YAML changeset appended: {yaml_updated}")
    for t, vals in by_table.items():
        print(f"  {t}: {len(vals)} Chinese literals, "
              f"{len(filter_glossary_used(used, vals))} keys")

    short_rem = [s for s in remaining if len(s) < 80]
    print(f"Remaining short (<80): {len(short_rem)}", file=sys.stderr)
    print("=== Remaining untranslated (first 50) ===", file=sys.stderr)
    for s in remaining[:50]:
        preview = s.replace("\n", "\\n")
        if len(preview) > 120:
            preview = preview[:120] + "..."
        print(preview, file=sys.stderr)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
